package main

import (
	"fmt"
)

func main() {
	var n int
	fmt.Scan(&n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
	}

	left := 0
	for left+1 < n && a[left] < a[left+1] {
		left++
	}

	right := n - 1
	for right > 0 && a[right] < a[right-1] {
		right--
	}

	for i := left; i < right; i++ {
		if a[i] != a[right] {
			fmt.Println("NO")
			return
		}
	}

	fmt.Println("YES")
}

